function buildCommand() {
  const __args = [['setpp'], 'Owner', 'Change the bot\'s own WhatsApp profile picture', async ({ sock, from, msg, args }) => {
  const url = args[0];
  const quotedImage = msg.message.extendedTextMessage?.contextInfo?.quotedMessage?.imageMessage;
  if (!url && !quotedImage) return sock.sendMessage(from, { text: 'Usage: .setpp <image-url>\nOr reply to an image with .setpp' }, { quoted: msg });
  try {
    let buffer;
    if (url) {
      const res = await fetch(url);
      buffer = Buffer.from(await res.arrayBuffer());
    } else {
      const { downloadMediaMessage } = require('@whiskeysockets/baileys');
      buffer = await downloadMediaMessage({ message: { imageMessage: quotedImage } }, 'buffer', {});
    }
    await sock.updateProfilePicture(sock.user.id, buffer);
    await sock.sendMessage(from, { text: '✅ Bot profile picture updated.' }, { quoted: msg });
  } catch (e) {
    await sock.sendMessage(from, { text: '⚠️ Could not update profile picture.' }, { quoted: msg });
  }
}, { ownerOnly: true }];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
